```json
{
  "root_causes": [
    {
      "service": "ts-order-other-service",
      "fault_kind": "database_call_slow",
      "evidence": [
        {"kind": "trace", "sql": "SELECT span_name, count(*) n, approx_quantile(duration,0.95)/1e6 p95_ms, approx_quantile(duration,0.5)/1e6 p50_ms FROM abnormal_traces WHERE service_name='ts-order-other-service' AND span_name IN ('SELECT ts.orders_other','Transaction.commit') GROUP BY 1", "claim": "Order-other's DB spans (SELECT ts.orders_other, Transaction.commit) have p95 of about 416ms and 852ms, while p50 stays near 0.3ms."},
        {"kind": "trace", "sql": "SELECT span_name, count(*) n, approx_quantile(duration,0.95)/1e6 p95_ms FROM normal_traces WHERE service_name='ts-order-other-service' AND span_name IN ('SELECT ts.orders_other','Transaction.commit') GROUP BY 1", "claim": "In the normal period the same DB spans had p95 of about 0.4ms and 1.9ms."},
        {"kind": "trace", "sql": "SELECT service_name, span_name, count(*) n, approx_quantile(duration,0.95)/1e6 p95_ms FROM abnormal_traces WHERE service_name='ts-order-other-service' AND attr_span_kind='Server' GROUP BY 1,2", "claim": "Order-other's own server spans (findAllOrder, refresh, tickets) slowed to p95 of 2.5s, 426ms and 219ms."},
        {"kind": "metric", "sql": "SELECT service_name, metric, avg(CAST(value AS DOUBLE)) v FROM abnormal_metrics WHERE service_name='ts-order-other-service' AND metric IN ('k8s.pod.cpu.usage','container.memory.working_set') GROUP BY 1,2", "claim": "Order-other CPU and memory stay flat or lower in the incident, so the slowness is not resource saturation."}
      ]
    }
  ],
  "propagation": [
    {"from": "ts-order-other-service", "to": "ts-admin-order-service",
     "evidence": [{"kind": "trace", "sql": "SELECT service_name, span_name, count(*) n, approx_quantile(duration,0.95)/1e6 p95_ms FROM abnormal_traces WHERE service_name='ts-admin-order-service' AND attr_span_kind='Server' GROUP BY 1,2", "claim": "Admin-order server spans slowed to p95 about 1,069ms while its own self time stayed small, consistent with waiting on order-other."}]},
    {"from": "ts-order-other-service", "to": "ts-seat-service",
     "evidence": [{"kind": "trace", "sql": "SELECT service_name, span_name, count(*) n, approx_quantile(duration,0.95)/1e6 p95_ms FROM abnormal_traces WHERE service_name='ts-seat-service' AND attr_span_kind='Client' GROUP BY 1,2", "claim": "Seat-service POST client calls, which go to order-other, rose to p95 about 216ms while GET calls stayed normal."}]},
    {"from": "ts-seat-service", "to": "ts-travel2-service",
     "evidence": [{"kind": "trace", "sql": "SELECT service_name, span_name, count(*) n, approx_quantile(duration,0.95)/1e6 p95_ms FROM abnormal_traces WHERE service_name='ts-travel2-service' AND attr_span_kind='Server' GROUP BY 1,2", "claim": "Travel2 server spans for trips/left slowed to p95 about 252ms, which the survey ties to its seat-service calls."}]},
    {"from": "ts-admin-order-service", "to": "ts-ui-dashboard",
     "evidence": [{"kind": "trace", "sql": "SELECT service_name, span_name, count(*) n, approx_quantile(duration,0.95)/1e6 p95_ms FROM abnormal_traces WHERE service_name='ts-ui-dashboard' AND span_name='GET /api/v1/adminorderservice/adminorder' GROUP BY 1,2", "claim": "The user-facing GET adminorder endpoint on ui-dashboard rose to p95 of about 949ms, from 19ms normally."}]},
    {"from": "ts-order-other-service", "to": "ts-ui-dashboard",
     "evidence": [{"kind": "trace", "sql": "SELECT service_name, span_name, count(*) n, approx_quantile(duration,0.95)/1e6 p95_ms FROM abnormal_traces WHERE service_name='ts-ui-dashboard' AND span_name='POST /api/v1/orderOtherService/orderOther/refresh' GROUP BY 1,2", "claim": "The user-facing orderOther refresh endpoint on ui-dashboard rose to p95 of about 426ms, from 4ms normally."}]}
  ]
}
